15|    {
16|        // Cache maintenance — hourly
17|        $schedule->command('cache:prune-stale')->hourly();
18|
19|        // Recurring todos — daily at 02:00 Tehran time
20|        $schedule->command('todos:generate-recurring')->dailyAt('02:00');
21|
22|        // Maintenance tasks — daily at 03:00 Tehran time
23|        $schedule->command('maintenance:generate-due')->dailyAt('03:00');
24|
25|        // Data archival — weekly Monday 04:00 Tehran time
26|        $schedule->command('data:archive')->weeklyOn(1, '04:00');
27|
28|        // Report generation — daily at 06:00 Tehran time
29|        $schedule->command('reports:generate-daily')->dailyAt('06:00');
30|
31|        // Zabbix sync — every 5 minutes (dispatched as queued job)
