4|use App\Http\Middleware\SafeRoleOrPermission;
5|use App\Http\Middleware\SecurityHeaders;
6|use App\Http\Middleware\ValidateUnitContext;
7|use Illuminate\Database\Eloquent\ModelNotFoundException;
8|use Illuminate\Foundation\Application;
9|use Illuminate\Foundation\Configuration\Exceptions;
10|use Illuminate\Foundation\Configuration\Middleware;
11|use Illuminate\Http\Request;
12|use Laravel\Sanctum\Http\Middleware\CheckAbilities;
13|use Laravel\Sanctum\Http\Middleware\CheckForAnyAbility;
14|use Sentry\Laravel\Integration;
15|use Spatie\Permission\Middleware\PermissionMiddleware;
16|use Spatie\Permission\Middleware\RoleMiddleware;
17|use Spatie\Permission\Middleware\RoleOrPermissionMiddleware;
18|use Symfony\Component\HttpKernel\Exception\NotFoundHttpException;
19|
20|return Application::configure(basePath: dirname(__DIR__))
21|    ->withRouting(
22|        web: __DIR__.'/../routes/web.php',
23|        api: __DIR__.'/../routes/api.php',
24|        commands: __DIR__.'/../routes/console.php',
25|        health: '/up',
26|    )
27|    ->withMiddleware(function (Middleware $middleware) {
28|        $middleware->statefulApi();
29|        // Browser-submitted CSP reports arrive without a CSRF token (#742).
30|        $middleware->validateCsrfTokens(except: ['csp-report']);
31|        $middleware->alias([
32|            'role' => RoleMiddleware::class,
33|            'permission' => PermissionMiddleware::class,
34|            'role_or_permission' => RoleOrPermissionMiddleware::class,
35|            'safe_role_or_permission' => SafeRoleOrPermission::class,
36|            'unit_context' => ValidateUnitContext::class,
37|            'last.activity' => LastUserActivity::class,
38|            'abilities' => CheckAbilities::class,
39|            'ability' => CheckForAnyAbility::class,
40|        ]);
41|        $middleware->web(append: [
42|            SecurityHeaders::class,
43|            LastUserActivity::class,
44|        ]);
45|
46|        // Trust proxies for HTTPS detection behind Cloudflare/load balancer.
47|        //
48|        // Issue #855: this defaulted to '*', which TrustProxies expands to
49|        // setTrustedProxies(['0.0.0.0/0', '::/0'], …) — every address on the
50|        // internet became a trusted proxy, so a client-supplied
51|        // X-Forwarded-Host/-Proto/-Port/-Prefix became the root of every
52|        // generated absolute URL (notification rows, paginator `links`,
53|        // asset(), and the guest redirect all inherit it).
54|        //
55|        // The default is now null — trust nothing — which is correct for the
56|        // documented direct nginx+FPM deployment. A deployment that DOES sit
57|        // behind a proxy must pin its ranges explicitly in TRUSTED_PROXIES,
58|        // then run `config:clear` / `optimize`: a cached config freezes the
59|        // value read here at boot (LoadEnvironmentVariables returns early when
60|        // config is cached), so editing .env alone would not take effect.
61|        //
62|        // X-Forwarded-For is deliberately NOT in the bitmask (#321): with an
63|        // unbounded trust list a client could forge its own IP, poisoning both
64|        // the throttle key and the audit-log IP column. That decision only
65|        // holds once the proxy list is pinned — reconciled in PR #878's
66|        // sibling (#855) body.
67|        $trustedProxies = env('TRUSTED_PROXIES');
68|        $middleware->trustProxies(
69|            at: $trustedProxies,
70|            headers: Request::HEADER_X_FORWARDED_HOST | Request::HEADER_X_FORWARDED_PROTO | Request::HEADER_X_FORWARDED_PORT | Request::HEADER_X_FORWARDED_PREFIX
71|        );
72|
73|        // Backstop that makes a wrong TRUSTED_PROXIES fail closed: with a host
74|        // allowlist, Request::getHost() throws on a host outside it instead of
75|        // silently adopting the client's value. Left empty, the allowlist
76|        // falls back to APP_URL — so a real deployment must set APP_URL (or
77|        // TRUSTED_HOSTS) to the hostname it actually serves.
78|        $middleware->trustHosts(at: array_filter(explode(',', (string) env('TRUSTED_HOSTS', ''))));
79|    })
80|    ->withExceptions(function (Exceptions $exceptions) {
81|        $exceptions->shouldRenderJsonWhen(function ($request) {
82|            return $request->is('api/*') || $request->expectsJson();
83|        });
84|
85|        // Custom handling for NotFoundHttpException to return clean 404 responses
86|        $exceptions->render(function (NotFoundHttpException $e, $request) {
87|            if ($request->is('api/*') || $request->expectsJson()) {
88|                // In debug mode, return the full exception details
89|                if (config('app.debug')) {
90|                    return response()->json([
91|                        'message' => $e->getMessage(),
92|                        'exception' => get_class($e),
93|                    ], 404);
94|                }
95|
96|                // In production, return a clean 404 message
97|                return response()->json([
98|                    'message' => 'Not Found',
99|                ], 404);
100|            }
101|        });
102|
103|        // Custom handling for ModelNotFoundException (route model binding 404s)
104|        $exceptions->render(function (ModelNotFoundException $e, $request) {
105|            if ($request->is('api/*') || $request->expectsJson()) {
106|                // In debug mode, return the full exception details
107|                if (config('app.debug')) {
108|                    return response()->json([
109|                        'message' => $e->getMessage(),
110|                        'exception' => get_class($e),
111|                    ], 404);
112|                }
113|
114|                // In production, return a clean 404 message
115|                return response()->json([
116|                    'message' => 'Not Found',
117|                ], 404);
118|            }
119|        });
120|
121|        // Register Sentry exception handler — captures unhandled exceptions and sends them to Sentry
122|        Integration::handles($exceptions);
