29|
30|        if ($dryRun) {
31|            $this->warn('  Dry run — no tickets were created.');
32|            $this->info('Maintenance task generation complete.');
33|
34|            return 0;
35|        }
36|
37|        $created = 0;
38|        foreach ($schedules as $schedule) {
39|            // Issue #533: idempotency guard — skip if an open ticket already exists
40|            // for this schedule (prevents duplicates on scheduler overlap or crash)
41|            $existingTicket = Ticket::where('unit_id', $schedule->unit_id)
42|                ->where('subject', $schedule->title)
43|                ->where('status', '!=', 'completed')
44|                ->where('created_at', '>=', now()->subDay())
45|                ->exists();
46|
47|            if ($existingTicket) {
48|                $this->warn("  Skipping schedule #{$schedule->id} — open ticket already exists.");
49|                // Still advance the schedule to avoid getting stuck
50|                $interval = max(1, (int) $schedule->recurrence_interval);
51|                $next = match ($schedule->frequency) {
52|                    'daily' => now()->addDays($interval),
53|                    'weekly' => now()->addWeeks($interval),
54|                    'monthly' => now()->addMonths($interval),
55|                    default => now()->addMonths($interval),
