{"content": "1|<?php
2|
3|namespace App\Services;
4|
5|use Illuminate\Support\Facades\Cache;
6|
7|class CacheInvalidationService implements CacheInvalidationServiceInterface
8|{
9|    /**
10|     * Pending namespace increments during a batch scope.
11|     *
12|     * @var array<string, true>
13|     */
14|    private array $pending = [];
15|
16|    /**
17|     * Whether a batch scope is currently active.
18|     */
19|    private bool $batching = false;
20|
21|    /**
22|     * Bump the version counter for a namespace.
23|     *
24|     * Cache keys follow the pattern: {namespace}:v{version}:{scopeHash}:{extra}
25|     * Incrementing the version makes all existing keys unreachable; they expire via TTL.
26|     *
27|     * When inside a batch scope, increments are collected and flushed once
28|     * at the end — repeated increments for the same namespace are deduplicated.
29|     */
30|    public function increment(string $namespace): int
31|    {
32|        if ($this->batching) {
33|            $this->pending[$namespace] = true;
34|
35|            return $this->getVersion($namespace);
36|        }
37|
38|        return Cache::increment("{$namespace}_version");
39|    }
40|
41|    public function flushPending(): int
42|    {
43|        $count = count($this->pending);
44|
45|        foreach (array_keys($this->pending) as $ns) {
46|            Cache::increment("{$ns}_version");
47|        }
48|        $this->pending = [];
49|
50|        return $count;
51|    }
52|
53|    public function batch(\Closure $callback): mixed
54|    {
55|        $this->batching = true;
56|        $this->pending = [];
57|
58|        try {
59|            $result = $callback();
60|        } finally {
61|            $this->flushPending();
62|            $this->batching = false;
63|        }
64|
65|        return $result;
66|    }
67|
68|    public function getVersion(string $namespace): int
69|    {
70|        return Cache::get("{$namespace}_version", 0);
71|    }
72|
73|    public function cacheKey(string $namespace, string $scopeHash, string $extra = 'none'): string
74|    {
75|        $version = $this->getVersion($namespace);
76|
77|        return "{$namespace}:v{$version}:{$scopeHash}:{$extra}";
78|    }
79|
80|    public function remember(string $namespace, string $scopeHash, \Closure $callback, int $ttlMinutes = 60, array $extra = []): mixed
81|    {
82|        $extraHash = empty($extra) ? 'none' : md5(serialize($extra));
83|        $key = $this->cacheKey($namespace, $scopeHash, $extraHash);
84|
85|        return Cache::remember($key, now()->addMinutes($ttlMinutes), $callback);
86|    }
