5|/**
6| * Typed outcome of one Zabbix call (#741).
7| *
8| * The controllers used to catch \Throwable around raw service calls, so a
9| * connection problem was an exception travelling through HTTP code. This
10| * result object makes the failure an ordinary value: `failed()` + a failure
11| * kind the controller maps to its (unchanged) 503 contract.
12| *
13| * Failure kinds: `timeout`, `connection`, `invalid_response`, `error`.
14| */
15|final class ZabbixResult
16|{
17|    /**
18|     * @param  mixed  $data  payload when successful
19|     * @param  string|null  $failure  one of timeout|connection|invalid_response|error
20|     */
21|    private function __construct(
22|        private readonly bool $ok,
23|        private readonly mixed $data,
24|        private readonly ?string $failure,
25|        private readonly ?string $message,
26|    ) {}
27|
28|    public static function success(mixed $data): self
29|    {
30|        return new self(true, $data, null, null);
31|    }
32|
33|    public static function fail(string $failure, string $message): self
34|    {
35|        return new self(false, null, $failure, $message);
36|    }
37|
38|    public function isOk(): bool
39|    {
40|        return $this->ok;
41|    }
42|
43|    public function failed(): bool
44|    {
45|        return ! $this->ok;
46|    }
47|
48|    public function data(): mixed
49|    {
50|        return $this->data;
51|    }
52|
53|    public function failure(): ?string
54|    {
55|        return $this->failure;
56|    }
57|
58|    public function message(): ?string
