209|                    'status' => 'error',
210|                    'message' => "واحد {$unit->name} در واحدهای قابل دسترس شما نیست",
211|                    'data' => $data,
212|                ];
213|                $this->importResults['skipped']++;
214|
215|                return;
216|            }
217|        } else {
218|            $this->importResults['preview'][] = [
219|                'row' => $rowNumber,
220|                'status' => 'error',
221|                'message' => 'شناسه واحد (u_id) خالی است',
222|                'data' => $data,
223|            ];
224|            $this->importResults['skipped']++;
225|
226|            return;
227|        }
228|
229|        // Verify related models exist (using pre-loaded data)
230|        $validationError = $this->validateRelatedModels($data);
231|        if ($validationError) {
232|            $this->importResults['preview'][] = [
233|                'row' => $rowNumber,
234|                'status' => 'error',
235|                'message' => $validationError,
236|                'data' => $data,
237|            ];
238|            $this->importResults['skipped']++;
239|
240|            return;
241|        }
242|
243|        // Find existing record by n_code
244|        $existing = $this->findExistingRecord($data);
245|        $matchKey = $existing ? ($existing['key'] ?? 'unknown') : null;
246|
247|        if ($existing) {
248|            $changes = $this->detectChanges($existing['record'], $data);
249|
250|            if (! empty($changes)) {
251|                $this->importResults['preview'][] = [
252|                    'row' => $rowNumber,
253|                    'status' => 'update',
254|                    'n_code' => $existing['record']->n_code,
255|                    'match_key' => $matchKey,
256|                    'changes' => $changes,
257|                    'person' => $existing['record']->f_name.' '.$existing['record']->l_name,
258|                    'data' => $data,
259|                ];
260|                $this->importResults['updated']++;
261|            } else {
262|                $this->importResults['preview'][] = [
263|                    'row' => $rowNumber,
264|                    'status' => 'unchanged',
265|                    'n_code' => $existing['record']->n_code,
266|                    'match_key' => $matchKey,
267|                    'message' => 'بدون تغییر',
268|                    'person' => $existing['record']->f_name.' '.$existing['record']->l_name,
269|                    'data' => $data,
270|                ];
271|                $this->importResults['skipped']++;
272|            }
273|        } else {
274|            $this->importResults['preview'][] = [
275|                'row' => $rowNumber,
276|                'status' => 'create',
277|                'n_code' => $data['n_code'],
278|                'person' => $data['f_name'].' '.$data['l_name'],
279|                'data' => $data,
280|            ];
281|            $this->importResults['created']++;
282|        }
283|    }
284|
285|    private function findExistingRecord(array $data): ?array
286|    {
287|        $existing = null;
288|        $matchKey = null;
289|
290|        if (! empty($data['n_code']) && isset($this->existingRecords['n_code'][$data['n_code']])) {
291|            $existing = $this->existingRecords['n_code'][$data['n_code']];
292|            $matchKey = 'n_code';
293|        }
294|
295|        if ($existing) {
296|            return ['record' => $existing, 'key' => $matchKey];
297|        }
298|
299|        return null;
300|    }
301|
302|    private function mapRowToData(array $row): array
303|    {
304|        // Expected CSV headers: n_code, f_name, l_name, t_id, e_id, r_id, s_id, u_id, phone
305|        return [
306|            'n_code' => $this->clean($row['n_code'] ?? null),
307|            'f_name' => $this->clean($row['f_name'] ?? null),
308|            'l_name' => $this->clean($row['l_name'] ?? null),
309|            't_id' => $this->parseInt($row['t_id'] ?? null),
310|            'e_id' => $this->parseInt($row['e_id'] ?? null),
311|            'r_id' => $this->parseInt($row['r_id'] ?? null),
312|            's_id' => $this->parseInt($row['s_id'] ?? null),
313|            'u_id' => $this->parseInt($row['u_id'] ?? null),
314|            'phone' => $this->clean($row['phone'] ?? null),
315|        ];
316|    }
317|
318|    private function validateRelatedModels(array $data): ?string
319|    {
320|        if (! empty($data['t_id']) && ! isset($this->tahsils[$data['t_id']])) {
321|            return "تحصیلات با شناسه {$data['t_id']} یافت نشد";
322|        }
323|        if (! empty($data['e_id']) && ! isset($this->estekhdams[$data['e_id']])) {
324|            return "نوع استخدام با شناسه {$data['e_id']} یافت نشد";
325|        }
326|        if (! empty($data['r_id']) && ! isset($this->radifs[$data['r_id']])) {
327|            return "ردیف سازمانی با شناسه {$data['r_id']} یافت نشد";
328|        }
329|        if (! empty($data['s_id']) && ! isset($this->semats[$data['s_id']])) {
330|            return "سمت با شناسه {$data['s_id']} یافت نشد";
331|        }
332|
333|        return null;
334|    }
335|
336|    private function processRow(array $row, int $rowNumber, string $action = 'auto', bool $isConfirmation = false): void
337|    {
338|        $data = $this->mapRowToData($row);
339|
340|        // Validate required fields
341|        if (empty($data['n_code']) || empty($data['f_name']) || empty($data['l_name'])) {
342|            $this->importResults['errors'][] = [
343|                'row' => $rowNumber,
344|                'error' => 'Missing required fields: n_code, f_name, l_name are required',
345|                'data' => $data,
346|            ];
347|            $this->importResults['skipped']++;
348|
349|            return;
350|        }
351|
352|        // Verify unit exists and is in accessible units (using pre-loaded data)
353|        $unit = $this->units[$data['u_id']] ?? null;
354|        if (! $unit) {
355|            $this->importResults['errors'][] = [
356|                'row' => $rowNumber,
357|                'error' => "Unit with id {$data['u_id']} not found",
358|                'data' => $data,
359|            ];
360|            $this->importResults['skipped']++;
361|
362|            return;
363|        }
364|
365|        // UNCONDITIONAL membership test (issue #839): the `! empty(...)` conjunct
366|        // made this `! empty([]) && ...` = false, i.e. ACCEPT the row. Under an
367|        // empty scope `$this->units` is empty, so the "not found" check above
368|        // already rejected it — this is a defence-in-depth backstop.
369|        if (! in_array($unit->id, $this->accessibleUnitIds)) {
370|            $this->importResults['errors'][] = [
371|                'row' => $rowNumber,
372|                'error' => "Unit {$data['u_id']} is not in your accessible units",
373|                'data' => $data,
374|            ];
375|            $this->importResults['skipped']++;
376|
377|            return;
378|        }
379|
380|        // Verify related models exist (using pre-loaded data)
381|        $validationError = $this->validateRelatedModels($data);
382|        if ($validationError) {
383|            $this->importResults['errors'][] = [
384|                'row' => $rowNumber,
385|                'error' => $validationError,
386|                'data' => $data,
387|            ];
388|            $this->importResults['skipped']++;
389|
390|            return;
391|        }
392|
393|        // Find existing record by n_code
394|        $existing = $this->findExistingRecord($data);
395|        $matchKey = $existing ? ($existing['key'] ?? 'unknown') : null;
396|
397|        if ($existing) {
398|            // Check for changes
399|            $changes = $this->detectChanges($existing['record'], $data);
400|
401|            if (! empty($changes)) {
402|                $this->importResults['changes'][] = [
403|                    'row' => $rowNumber,
404|                    'n_code' => $existing['record']->n_code,
405|                    'match_key' => $matchKey,
406|                    'changes' => $changes,
407|                ];
408|
409|                // Update the record
410|                if ($action === 'update' || $action === 'auto') {
411|                    $existing['record']->update($data);
412|                    $this->importResults['updated']++;
413|                }
414|            } else {
415|                $this->importResults['skipped']++;
416|            }
417|        } else {
418|            // Create new record
419|            if ($action === 'create' || $action === 'auto') {
420|                Person::create($data);
421|                $this->importResults['created']++;
422|            }
423|        }
424|    }
425|
426|    private function detectChanges(Person $existing, array $newData): array
427|    {
428|        $changes = [];
429|        $compareFields = ['f_name', 'l_name', 't_id', 'e_id', 'r_id', 's_id', 'u_id', 'phone'];
430|
431|        foreach ($compareFields as $field) {
432|            $oldValue = $existing->$field;
433|            $newValue = $newData[$field] ?? null;
434|
435|            // Normalize for comparison
436|            $oldNormalized = $this->normalizeForComparison($oldValue);
437|            $newNormalized = $this->normalizeForComparison($newValue);
438|
439|            if ($oldNormalized !== $newNormalized) {
440|                $changes[$field] = [
441|                    'old' => $oldValue,
442|                    'new' => $newValue,
443|                ];
444|            }
445|        }
446|
447|        return $changes;
448|    }
449|
450|    private function normalizeForComparison($value): ?string
451|    {
452|        if ($value === null || $value === '' || $value === '\\N') {
453|            return null;
454|        }
455|
456|        return trim((string) $value);
457|    }
458|
459|    private function parseInt($value): ?int
460|    {
461|        if ($value === null || $value === '' || $value === '\\N') {
462|            return null;
463|        }
464|        $val = trim((string) $value);
465|        if ($val === '' || $val === '\\N') {
466|            return null;
467|        }
468|
469|        return (int) $val;
470|    }
471|
472|    private function clean($value): ?string
473|    {
474|        if ($value === null || $value === '' || $value === '\\N' || trim((string) $value) === '') {
475|            return null;
476|        }
477|
478|        return trim((string) $value);
479|    }
480|
481|    public function getImportResults(): array
482|    {
483|        return $this->importResults;
484|    }
485|
486|    public function getCsvSettings(): array
487|    {
488|        return [
489|            'delimiter' => "\t",
490|            'enclosure' => '"',
491|            'escape_character' => '\\',
492|            'contiguous' => false,
493|            'input_encoding' => 'UTF-8',
494|        ];
495|    }
