3|namespace App\Exports;
4|
5|use App\Models\Region;
6|use App\Models\Unit;
7|use Illuminate\Support\Collection;
8|use Maatwebsite\Excel\Concerns\FromCollection;
9|use Maatwebsite\Excel\Concerns\ShouldAutoSize;
10|use Maatwebsite\Excel\Concerns\WithEvents;
11|use Maatwebsite\Excel\Concerns\WithHeadings;
12|use Maatwebsite\Excel\Concerns\WithMapping;
13|use Maatwebsite\Excel\Concerns\WithTitle;
14|use Maatwebsite\Excel\Events\AfterSheet;
15|
16|/**
17| * One row per unit (flat table). The parent/child relationship is expressed by
18| * the «مسیر کامل» breadcrumb plus the «سطح» depth, so the sheet stays sortable
19| * and filterable in Excel instead of becoming a ragged column-per-level grid.
20| */
21|class UnitsExport implements FromCollection, ShouldAutoSize, WithEvents, WithHeadings, WithMapping, WithTitle
22|{
23|    /**
24|     * Column definitions: key => ['label' => Persian]
25|     *
26|     * @var array<string, array{label: string}>
27|     */
28|    protected array $columnDefs = [
29|        'id' => ['label' => 'شناسه'],
30|        'name' => ['label' => 'نام واحد'],
31|        'unit_type' => ['label' => 'نوع واحد'],
32|        'county' => ['label' => 'شهرستان'],
33|        'parent_name' => ['label' => 'والد مستقیم'],
34|        'full_path' => ['label' => 'مسیر کامل'],
35|        'depth' => ['label' => 'سطح'],
36|        'status' => ['label' => 'وضعیت'],
37|    ];
38|
39|    /** @var array<int, string> */
40|    protected array $columns = ['id', 'name', 'unit_type', 'county', 'parent_name', 'full_path', 'depth', 'status'];
41|
42|    /** @var Collection<int, Unit> */
43|    protected Collection $units;
44|
45|    /**
46|     * Pre-resolved hierarchy metadata per unit id, built by the controller in
47|     * one pass so mapping a row never walks parents (and never N+1s).
48|     *
49|     * @var array<int, array{path: string, depth: int, parent_name: string}>
50|     */
51|    protected array $hierarchy;
52|
53|    /**
54|     * @param  Collection<int, Unit>  $units  depth-first ordered (parents before children)
55|     * @param  array<int, array{path: string, depth: int, parent_name: string}>  $hierarchy
56|     */
57|    public function __construct(Collection $units, array $hierarchy)
58|    {
59|        $this->units = $units;
60|        $this->hierarchy = $hierarchy;
61|    }
62|
63|    /**
64|     * @return Collection<int, Unit>
65|     */
66|    public function collection(): Collection
67|    {
68|        return $this->units;
69|    }
70|
71|    public function headings(): array
72|    {
73|        return array_map(
74|            fn (string $key) => $this->columnDefs[$key]['label'],
75|            $this->columns
76|        );
77|    }
78|
79|    /**
80|     * @param  Unit  $unit
81|     */
82|    public function map($unit): array
83|    {
84|        $meta = $this->hierarchy[$unit->id] ?? ['path' => $unit->name, 'depth' => 0, 'parent_name' => ''];
85|
86|        return array_map(
87|            fn (string $key) => $this->resolveValue($unit, $key, $meta),
88|            $this->columns
89|        );
90|    }
91|
92|    /**
93|     * The county a unit sits in, for filtering the sheet by county name.
94|     *
95|     * `Unit::region_id` points at a `regions` row whose `type` is either
96|     * `province` or `county`. Only a county row is reported here — a unit
97|     * attached directly to a province has no county of its own, and showing
98|     * the province name in a column labelled «شهرستان» would be a lie that
99|     * also defeats filtering (one province name would swallow every unit
100|     * below it).
101|     */
102|    protected function resolveCounty(Unit $unit): string
103|    {
104|        $region = $unit->relationLoaded('region')
105|            ? $unit->region
106|            : Region::query()->find($unit->region_id);
107|
108|        if (! $region instanceof Region || $region->type !== 'county' || (string) $region->name === '') {
109|            return '-';
110|        }
111|
112|        return (string) $region->name;
113|    }
114|
115|    /**
116|     * @param  array{path: string, depth: int, parent_name: string}  $meta
117|     */
118|    protected function resolveValue(Unit $unit, string $key, array $meta): mixed
119|    {
120|        return match ($key) {
121|            'unit_type' => $unit->unitType->name ?? '-',
122|            'county' => $this->resolveCounty($unit),
123|            'parent_name' => $meta['parent_name'] !== '' ? $meta['parent_name'] : '-',
124|            'full_path' => $meta['path'],
125|            'depth' => $meta['depth'],
126|            'status' => $unit->is_active ? 'فعال' : 'غیرفعال',
127|            default => $unit->{$key} ?? '-',
128|        };
129|    }
130|
131|    public function title(): string
132|    {
133|        return 'واحدها';
134|    }
135|
136|    /**
137|     * @return array<string, callable>
138|     */
139|    public function registerEvents(): array
140|    {
141|        return [
142|            // Persian sheet: first column renders on the right, like the app UI.
143|            AfterSheet::class => function (AfterSheet $event): void {
144|                $event->sheet->getDelegate()->setRightToLeft(true);
145|            },
146|        ];
147|    }
