97|        return array_map(
98|            fn (string $key) => $this->resolveValue($person, $key),
99|            $this->columns
100|        );
101|    }
102|
103|    protected function resolveValue(Person $person, string $key): mixed
104|    {
105|        return match ($key) {
106|            'full_name' => $this->resolveFullName($person),
107|            'semat' => $person->semat->name ?? '-',
108|            'tahsil' => $person->tahsil->name ?? '-',
109|            'estekhdam' => $person->estekhdam->name ?? '-',
110|            'radif' => $person->radif->name ?? '-',
111|            'unit' => $this->resolveUnitPath($person),
112|            'status' => $this->resolveStatus($person),
113|            'birth_date' => $this->resolveJalaliDate($person->birth_date),
114|            'hire_date' => $this->resolveJalaliDate($person->hire_date),
115|            default => (string) ($person->{$key} ?? '-'),
116|        };
117|    }
118|
119|    /**
120|     * `Person::$name` falls back to «—» when both name parts are blank, which
121|     * is a UI affordance, not a name. The sheet gets a dash instead.
122|     */
123|    protected function resolveFullName(Person $person): string
124|    {
